import { api, PAGE_SIZE, urlUtils } from '@igblsln/store';
const API_PATH = '/tax/tds_entry/';
export const customApi = api.injectEndpoints({
    overrideExisting: false,
    endpoints: (build) => ({
        listSaleGSTEntries: build.query({
            query: ({ page, size, year, month }) => {
                return {
                    url: urlUtils(API_PATH, `?page=${page || 1}&page_size=${size || PAGE_SIZE}&year=${year}&month=${month}`),
                };
            },
        }),
        listSaleGSTReports: build.query({
            query: ({ page, size, year, month }) => {
                return {
                    url: urlUtils(API_PATH, `?page=${page || 1}&page_size=${size || PAGE_SIZE}&year=${year}&month=${month}`),
                };
            },
        }),
        getErrorProne: build.query({
            query: () => 'error-prone',
        }),
    }),
});
export const { useListSaleGSTEntriesQuery, useListSaleGSTReportsQuery, useGetErrorProneQuery } = customApi;
